    final Properties props = generateJobProperties(this.baseConfig, "testDoesCancelOnFailure", "_12345");
    props.setProperty(GobblinClusterConfigurationKeys.HELIX_WORKFLOW_SUBMISSION_TIMEOUT_SECONDS, "0");
