private void runWorkflowTest(Duration mockStepAmountTime, String jobSuffix, String newJobWorkflowIdSuffix, String updateWorkflowIdSuffix, String assertUpdateWorkflowIdSuffix, boolean isThrottleEnabled, boolean isSameWorkflow) throws Exception {
    Clock mockClock = Mockito.mock(Clock.class);
    AtomicReference<Instant> nextInstant = new AtomicReference<>(beginTime);
    when(mockClock.instant()).thenAnswer(invocation -> nextInstant.getAndAccumulate(null, (currentInstant, x) -> currentInstant.plus(mockStepAmountTime)));
    // Use GobblinHelixManagerFactory instead of HelixManagerFactory to avoid the connection error
    // helixManager is set to local variable to avoid the HelixManager (ZkClient) is not connected error across tests
    HelixManager helixManager = GobblinHelixManagerFactory.getZKHelixManager(helixClusterName, TestHelper.TEST_HELIX_INSTANCE_NAME, InstanceType.CONTROLLER, zkConnectingString);
    GobblinHelixJobScheduler jobScheduler = createJobScheduler(helixManager, isThrottleEnabled, mockClock);
    final Properties properties = GobblinHelixJobLauncherTest.generateJobProperties(this.baseConfig, jobSuffix, newJobWorkflowIdSuffix);
    NewJobConfigArrivalEvent newJobConfigArrivalEvent = createJobConfigArrivalEvent(properties);
    jobScheduler.handleNewJobConfigArrival(newJobConfigArrivalEvent);
    connectAndAssertWorkflowId(newJobWorkflowIdSuffix, newJobConfigArrivalEvent.getJobName(), helixManager);
    if (isSameWorkflow) {
        properties.setProperty(ConfigurationKeys.JOB_ID_KEY, "job_" + properties.getProperty(ConfigurationKeys.JOB_NAME_KEY) + updateWorkflowIdSuffix);
        jobScheduler.handleUpdateJobConfigArrival(new UpdateJobConfigArrivalEvent(properties.getProperty(ConfigurationKeys.JOB_NAME_KEY), properties));
        connectAndAssertWorkflowId(assertUpdateWorkflowIdSuffix, newJobConfigArrivalEvent.getJobName(), helixManager);
    } else {
        final Properties properties2 = GobblinHelixJobLauncherTest.generateJobProperties(this.baseConfig, jobSuffix + '2', updateWorkflowIdSuffix);
        NewJobConfigArrivalEvent newJobConfigArrivalEvent2 = new NewJobConfigArrivalEvent(properties2.getProperty(ConfigurationKeys.JOB_NAME_KEY), properties2);
        jobScheduler.handleUpdateJobConfigArrival(new UpdateJobConfigArrivalEvent(properties2.getProperty(ConfigurationKeys.JOB_NAME_KEY), properties2));
        connectAndAssertWorkflowId(assertUpdateWorkflowIdSuffix, newJobConfigArrivalEvent2.getJobName(), helixManager);
    }
}

