public void onAddSpecForAdhocFlowWhenSimilarExistingFlowIsCurrentlyLaunching() throws IOException {
    ConfigBuilder configBuilder = ConfigBuilder.create().addPrimitive(ConfigurationKeys.FLOW_GROUP_KEY, "testGroup").addPrimitive(ConfigurationKeys.FLOW_NAME_KEY, "testName").addPrimitive(ConfigurationKeys.FLOW_EXECUTION_ID_KEY, System.currentTimeMillis()).addPrimitive("gobblin.flow.sourceIdentifier", "source").addPrimitive("gobblin.flow.destinationIdentifier", "destination");
    Config config = configBuilder.build();
    FlowSpec flowSpec = FlowSpec.builder().withConfig(config).build();
    Mockito.when(dagManagementStateStore.existsCurrentlyLaunchingExecOfSameFlow("testGroup", "testName", FlowUtils.getOrCreateFlowExecutionId(flowSpec))).thenReturn(true);
    orchestrator.onAddSpec(flowSpec);
}

