@Test
public void testRetryCurrentFailedJob() throws Exception {
    String flowName = "fn5";
    Dag<JobExecutionPlan> dag = DagTestUtils.buildDag("1", flowExecutionId, DagProcessingEngine.FailureOption.FINISH_ALL_POSSIBLE.name(), 2, "user5", ConfigFactory.empty().withValue(ConfigurationKeys.FLOW_GROUP_KEY, ConfigValueFactory.fromAnyRef(flowGroup)).withValue(ConfigurationKeys.FLOW_NAME_KEY, ConfigValueFactory.fromAnyRef(flowName)).withValue(ConfigurationKeys.JOB_GROUP_KEY, ConfigValueFactory.fromAnyRef(flowGroup)).withValue(ConfigurationKeys.SPECEXECUTOR_INSTANCE_URI_KEY, ConfigValueFactory.fromAnyRef(MySqlDagManagementStateStoreTest.TEST_SPEC_EXECUTOR_URI)));
    Dag.DagId dagId = DagUtils.generateDagId(dag);
    List<SpecProducer<Spec>> specProducers = getDagSpecProducers(dag);
    dagManagementStateStore.addDag(dag);
    // a job status with shouldRetry=true, it should have execution status = PENDING_RETRY
    JobStatus jobStatus = JobStatus.builder().flowName(flowName).flowGroup(flowGroup).jobGroup(flowGroup).jobName("job0").flowExecutionId(flowExecutionId).message("Test message").eventName(ExecutionStatus.PENDING_RETRY.name()).startTime(flowExecutionId).shouldRetry(true).orchestratedTime(flowExecutionId).build();
    doReturn(new ImmutablePair<>(Optional.of(dag.getNodes().get(0)), Optional.of(jobStatus))).when(dagManagementStateStore).getDagNodeWithJobStatus(any());
    ReevaluateDagProc reEvaluateDagProc = new ReevaluateDagProc(new ReevaluateDagTask(new DagActionStore.DagAction(flowGroup, flowName, flowExecutionId, "job0", DagActionStore.DagActionType.REEVALUATE), null, dagManagementStateStore, mockedDagProcEngineMetrics), ConfigFactory.empty());
    reEvaluateDagProc.process(dagManagementStateStore, mockedDagProcEngineMetrics);
    // only the current job
    int numOfLaunchedJobs = 1;
    // only the current job, that was failed, should have been retried by the reevaluate dag proc, because jobStatus has shouldRetry=true
    Mockito.verify(specProducers.get(0), Mockito.times(1)).addSpec(any());
    // separately verified `specProducers.get(0)`
    specProducers.stream().skip(numOfLaunchedJobs).forEach(sp -> Mockito.verify(sp, Mockito.never()).addSpec(any()));
    Assert.assertFalse(DagProcUtils.isDagFinished(this.dagManagementStateStore.getDag(dagId).get()));
    Mockito.verify(dagManagementStateStore, Mockito.never()).deleteDagAction(any());
    Mockito.verify(dagManagementStateStore, Mockito.never()).deleteDag(any());
    Mockito.verify(dagManagementStateStore, Mockito.never()).addJobDagAction(any(), any(), anyLong(), any(), eq(DagActionStore.DagActionType.REEVALUATE));
}

