@Test
public void testExtractWorkUnitSizeInfo() throws Exception {
    // mock `FileStatus` having an encoded WorkUnitSizeInfo as filename
    List<FileStatus> fileStatuses = Arrays.asList(createMockFileStatus("/test/dir/multitask_n=3-total=100-median=100.0-mean=100.0-stddev=0.0_0.mwu"), createMockFileStatus("/test/dir/multitask_n=2-total=200-median=100.0-mean=100.0-stddev=0.0_1.mwu"), createMockFileStatus("/test/dir/task_n=1-total=300-median=100.0-mean=100.0-stddev=0.0_5.wu"), createMockFileStatus("/test/dir/multitask_n=4-total=400-median=100.0-mean=100.0-stddev=0.0_30.mwu"), createMockFileStatus("/test/dir/task_n=1-total=500-median=100.0-mean=100.0-stddev=0.0_2.wu"));
    Mockito.when(mockFileSystem.listStatus(Mockito.any(Path.class), Mockito.any(PathFilter.class))).thenReturn(fileStatuses.toArray(new FileStatus[0]));
    Optional<Workload.WorkSpan<WorkUnitClaimCheck>> span = workload.getSpan(0, 5);
    Assert.assertTrue(span.isPresent());
    Workload.WorkSpan<WorkUnitClaimCheck> workSpan = span.get();
    Assert.assertEquals(workSpan.getNumElems(), fileStatuses.size());
    Iterable<WorkUnitClaimCheck> workSpanIterable = () -> workSpan;
    List<WorkUnitClaimCheck> wuClaimChecks = StreamSupport.stream(workSpanIterable.spliterator(), false).collect(Collectors.toList());
    // note: since ordering is based on filename, it will not be the same as `fileStatuses` above
    for (WorkUnitClaimCheck workUnitClaimCheck : wuClaimChecks) {
        WorkUnitSizeInfo sizeInfo = workUnitClaimCheck.getWorkUnitSizeInfo();
        Assert.assertNotNull(sizeInfo);
        int n = sizeInfo.getNumConstituents();
        long expectedTotalSize = (n == 1 && workUnitClaimCheck.getWorkUnitPath().endsWith("_5.wu")) ? 300 : n == 1 ? 500 : n == 2 ? 200 : n == 3 ? 100 : n == 4 ? 400 : // unexpected (sentinel)
        -1;
        Assert.assertEquals(sizeInfo.getTotalSize(), expectedTotalSize);
    }
}

